def countTriplets(nums):
    def set_bits(x):
        count = 0
        while x > 0:
            count += x & 1
            x >>= 1
        return count

    n = len(nums)
    if n < 3:
        return 0

    even = 0
    odd = 0

    # Count how many numbers have even/odd set bits
    for num in nums:
        if set_bits(num) % 2 == 0:
            even += 1
        else:
            odd += 1

    # Helper for combinations nCk
    def comb(n, k):
        if n < k:
            return 0
        if k == 2:
            return n * (n - 1) // 2
        if k == 3:
            return n * (n - 1) * (n - 2) // 6
        return 0

    # Triplets:
    # - all three even
    # - one even + two odds
    res = comb(even, 3) + even * comb(odd, 2)
    return res
